  /** Maximum sustained requests per second (token bucket refill rate) */
  maxRps: number;
  /** Retry configuration per job */
  retry?: {
    /** Maximum retry attempts (0 = no retries) */
    maxRetries: number;
    /** Base delay in milliseconds before first retry */
    baseDelayMs: number;
  };
}

// ========================
// Token Bucket Limiter
// ========================

class TokenBucket {
  private tokens: number;
  private maxTokens: number;
  private refillRate: number; // tokens per second
  private lastRefill: number;

  constructor(maxRps: number) {
    if (maxRps <= 0) throw new Error('maxRps must be > 0');
    this.maxTokens = maxRps;
    this.tokens = maxRps; // Start full to allow initial burst
    this.refillRate = maxRps;
    this.lastRefill = Date.now();
  }

  private refill(): void {
    const now = Date.now();
    const elapsed = (now - this.lastRefill) / 1000;
    this.tokens = Math.min(this.maxTokens, this.tokens + elapsed * this.refillRate);
    this.lastRefill = now;
  }

  async acquire(signal?: AbortSignal): Promise<void> {
    while (true) {
      if (signal?.aborted) throw new DOMException('Aborted', 'AbortError');
      this.refill();

      if (this.tokens >= 1) {
        this.tokens -= 1;
        return;
      }

      // Calculate exact wait time until next token is available
      const waitMs = Math.max(0, ((1 - this.tokens) / this.refillRate) * 1000);
      await this.sleep(waitMs, signal);
    }
  }

  private sleep(ms: number, signal?: AbortSignal): Promise<void> {
    return new Promise<void>((resolve, reject) => {
      const timer = setTimeout(resolve, ms);
      if (signal) {
        signal.addEventListener('abort', () => {
          clearTimeout(timer);
          reject(new DOMException('Aborted', 'AbortError'));
        }, { once: true });
      }
    });
  }
}

// ========================
// Retry Logic
// ========================

async function withRetry<T>(
  fn: () => Promise<T>,
  maxRetries: number,
  baseDelayMs: number,
  signal?: AbortSignal
): Promise<T> {
  let lastError: Error | undefined;

  for (let attempt = 0; attempt <= maxRetries; attempt++) {
    if (signal?.aborted) throw new DOMException('Aborted', 'AbortError');

    try {
      return await fn();
    } catch (err) {
      lastError = err instanceof Error ? err : new Error(String(err));

      // Abort signals should not be retried
      if (lastError instanceof DOMException && lastError.name === 'AbortError') {
        throw lastError;
      }

      if (attempt === maxRetries) throw lastError;

      // Exponential backoff with additive jitter (0-50%)
      const exponentialDelay = baseDelayMs * Math.pow(2, attempt);
      const jitter = Math.random() * exponentialDelay * 0.5;
      const delay = exponentialDelay + jitter;

      await new Promise<void>((resolve, reject) => {
        const timer = setTimeout(resolve, delay);
        signal?.addEventListener('abort', () => {
          clearTimeout(timer);
          reject(new DOMException('Aborted', 'AbortError'));
        }, { once: true });
      });
    }
  }

  throw lastError!;
}

// ========================
// Queue Executor
// ========================

export async function runJobQueue<T>(
  jobs: Array<() => Promise<T>>,
  options: QueueOptions,
  signal?: AbortSignal
): Promise<QueueResult<T>> {
  const { maxConcurrency, maxRps, retry = { maxRetries: 3, baseDelayMs: 1000 } } = options;
  const bucket = new TokenBucket(maxRps);
  const results: JobResult<T>[] = new Array(jobs.length);
  let nextIdx = 0;

  const worker = async (): Promise<void> => {
    while (true) {
      if (signal?.aborted) break;

      // Synchronous index grab is safe in single-threaded JS event loop
      const idx = nextIdx++;
      if (idx >= jobs.length) break;

      try {
        // Rate limit before execution
        await bucket.acquire(signal);
        if (signal?.aborted) break;

        // Execute with retry semantics
        const value = await withRetry(jobs[idx], retry.maxRetries, retry.baseDelayMs, signal);
        results[idx] = { index: idx, success: true, value };
      } catch (err) {
        // If aborted, stop this worker gracefully
        if (signal?.aborted && err instanceof DOMException && err.name === 'AbortError') {
          break;
        }

        // Failure isolation: record error, continue to next job
        results[idx] = { index: idx, success: false, error: err instanceof Error ? err : new Error(String(err)) };
      }
    }
  };

  // Spawn worker pool
  const poolSize = Math.min(maxConcurrency, jobs.length);
  await Promise.all(Array.from({ length: poolSize }, () => worker()));

  // Aggregate results
  const successes = results.filter(r => r.success).length;
  const failures = results.filter(r => !r.success).length;
  const errors = results.filter(r => !r.success).map(r => ({ index: r.index, error: r.error! }));

  return { successes, failures, results, errors };
}
```

### Usage Example

```typescript
async function main() {
  const controller = new AbortController();
  const signal = controller.signal;

  // Simulate 50 ETL extraction jobs
  const jobs = Array.from({ length: 50 }, (_, i) => async () => {
    // Simulate network I/O or DB query
    await new Promise(res => setTimeout(res, 30 + Math.random() * 50));

    // 20% chance of transient failure
    if (Math.random() < 0.2) {
      throw new Error(`Transient timeout extracting record ${i}`);
    }

    return { id: i, payload: `data_${i}`, status: 'processed' };
  });

  const result = await runJobQueue(jobs, {
    maxConcurrency: 8,
    maxRps: 15,
    retry: { maxRetries: 3, baseDelayMs: 400 }
  }, signal);

  console.log(`Completed: ${result.successes} successes, ${result.failures} failures`);
  if (result.errors.length > 0) {
    console.log('Failed indices:', result.errors.map(e => e.index));
  }

  // Graceful cancellation example (e.g., on SIGINT or timeout)
  // controller.abort();
}

main().catch(console.error);
```

### Trade-offs & Design Notes

| Area | Decision | Rationale & Trade-off |
|------|----------|------------------------|
| **Token Bucket Initialization** | Starts full (`maxRps` tokens) | Allows an initial burst equal to the sustained rate, which is standard for ETL pipelines that often have cold-start latency. **Trade-off:** If you need strict zero-burst enforcement, you'd need to initialize `tokens = 0` or add a `maxBurst` config. |
| **Jitter Algorithm** | Additive jitter (`0–50%` of backoff) | Simpler and predictable. **Trade-off:** Doesn't fully eliminate thundering-herd synchronization like *Full Jitter* or *Equal Jitter*. For most ETL workloads hitting external APIs or DBs, additive jitter is sufficient and easier to debug. |
| **Concurrency Control** | Synchronous `nextIdx++` index grab | Safe in single-threaded JS because the increment happens synchronously before any `await`. **Trade-off:** Not thread-safe (irrelevant for Node/Browser). If you migrate to Worker Threads or Bun's multi-threading, you'd need an atomic counter or lock. |
| **AbortSignal Handling** | Breaks worker loops; does not force-kill running promises | **Graceful** means allowing in-flight I/O to complete or be cancelled by the job function itself. **Trade-off:** If a job doesn't internally check the signal, it may finish after cancellation. This is intentional: force-killing async operations can leave DB transactions or network sockets in inconsistent states. |
| **Result Storage** | In-memory array of all results | Simple, deterministic, and matches overnight batch semantics. **Trade-off:** Memory scales linearly with job count. For pipelines processing millions of items, you'd replace this with streaming sinks or checkpointing to disk/S3. |
| **Retry Scope** | Per-item, not per-batch | Failures are isolated. **Trade-off:** No bulk retry or dependency graph awareness. If job `N` fails permanently, it's recorded but doesn't block or retry dependent jobs. Suitable for independent ETL extraction/transform units. |

This implementation is optimized for **predictable throughput**, **safe cancellation**, and **observability** (structured results/errors). It avoids external dependencies, making it easy to audit, bundle, or adapt to internal infra standards.

